20	template <typename DstDType, typename SrcDType>
21	PTO_INTERNAL void ConvertToDstDtype(
22	    __ubuf__ DstDType* dst, __ubuf__ SrcDType* src, uint8_t repeatNum, uint16_t dstBlockStride, uint16_t srcBlockStride,
23	    uint16_t dstRepeatStride, uint16_t srcRepeatStride)
24	{
25	    if constexpr (std::is_same<DstDType, float>::value && std::is_same<SrcDType, int16_t>::value) {
26	        vconv_s162f32(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
27	        pipe_barrier(PIPE_V);
28	    } else if constexpr (std::is_same<DstDType, half>::value && std::is_same<SrcDType, int8_t>::value) {
29	        vconv_s82f16(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
30	        pipe_barrier(PIPE_V);
31	    } else if constexpr (std::is_same<DstDType, float>::value && std::is_same<SrcDType, half>::value) {
32	        vconv_f162f32(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
33	        pipe_barrier(PIPE_V);
34	    }
35	}
36	
37	template <typename DstDType, typename SrcDType, unsigned dstRowStride, unsigned srcRowStride>
38	PTO_INTERNAL void ConvertForDequant(
39	    __ubuf__ DstDType* dstPtr, __ubuf__ SrcDType* srcPtr, unsigned dstValidRows, unsigned dstValidCols)
40	{
41	    set_mask_count();
42	    set_vector_mask(0, dstValidCols);
43	    for (uint32_t i = 0; i < dstValidRows; i++) {
44	        if constexpr (std::is_same_v<DstDType, float> && std::is_same_v<SrcDType, int8_t>) {
45	            ConvertToDstDtype<half, SrcDType>(
46	                (__ubuf__ half*)(dstPtr + i * dstRowStride), srcPtr + i * srcRowStride, 0, 2, 1,
47	                BLOCK_MAX_PER_REPEAT * 2, BLOCK_MAX_PER_REPEAT / 2);
48	            ConvertToDstDtype<DstDType, half>(
49	                dstPtr + i * dstRowStride, (__ubuf__ half*)(dstPtr + i * dstRowStride), 0, 1, 2, BLOCK_MAX_PER_REPEAT,
50	                BLOCK_MAX_PER_REPEAT);
51	        } else {
52	            constexpr unsigned repeatWidth = sizeof(DstDType) > sizeof(SrcDType) ? sizeof(DstDType) : sizeof(SrcDType);
53	            constexpr unsigned dstRepeatStride = repeatWidth == sizeof(DstDType) ?
54	                                                     BLOCK_MAX_PER_REPEAT :
55	                                                     (BLOCK_MAX_PER_REPEAT / sizeof(SrcDType) * sizeof(DstDType));
56	            constexpr unsigned srcRepeatStride = repeatWidth == sizeof(SrcDType) ?
57	                                                     BLOCK_MAX_PER_REPEAT :
58	                                                     (BLOCK_MAX_PER_REPEAT / sizeof(DstDType) * sizeof(SrcDType));
59	            ConvertToDstDtype<DstDType, SrcDType>(
60	                dstPtr + i * dstRowStride, srcPtr + i * srcRowStride, 0, 1, 1, dstRepeatStride, srcRepeatStride);
61	        }
62	    }
63	    set_mask_norm();
64	    set_vector_mask(-1, -1);
65	}
66	
67	template <typename T, unsigned dstRowStride, unsigned scaleRowStride>
68	PTO_INTERNAL void ApplyScaleAndOffset(
69	    __ubuf__ T* dstPtr, __ubuf__ T* scalePtr, __ubuf__ T* offsetPtr, unsigned dstValidRows, unsigned dstValidCols)
70	{
71	    set_mask_count();
72	    set_vector_mask(0, dstValidCols);
73	    for (int i = 0; i < dstValidRows; ++i) {
74	        __ubuf__ T* dstNext = dstPtr + i * dstRowStride;
75	        set_flag(PIPE_V, PIPE_S, EVENT_ID0);
76	        wait_flag(PIPE_V, PIPE_S, EVENT_ID0);
77	        T offsetValue = *(offsetPtr + i * scaleRowStride);
78	        T scaleValue = *(scalePtr + i * scaleRowStride);
79	        set_flag(PIPE_S, PIPE_V, EVENT_ID0);
80	        wait_flag(PIPE_S, PIPE_V, EVENT_ID0);
81	        vadds(dstNext, dstNext, -offsetValue, 1, 1, 1, 8, 8);
82	        pipe_barrier(PIPE_V);
83	        vmuls(dstNext, dstNext, scaleValue, 1, 1, 1, 8, 8);
84	        pipe_barrier(PIPE_V);
85	    }
86	    set_mask_norm();
87	    set_vector_mask(-1, -1);
88	}
89	
90	template <
91	    typename TileDataDst, typename TileDataSrc, typename TileDataPara, unsigned dstRowStride, unsigned srcRowStride,
92	    unsigned scaleRowStride>
93	__tf__ PTO_INTERNAL void TDequant(
94	    typename TileDataDst::TileDType __out__ dst, typename TileDataSrc::TileDType __in__ src,
95	    typename TileDataPara::TileDType __in__ scale, typename TileDataPara::TileDType __in__ offset,
96	    unsigned dstValidRows, unsigned dstValidCols)
97	{
98	    __ubuf__ typename TileDataDst::DType* dstPtr = (__ubuf__ typename TileDataDst::DType*)__cce_get_tile_ptr(dst);
99	    __ubuf__ typename TileDataSrc::DType* srcPtr = (__ubuf__ typename TileDataSrc::DType*)__cce_get_tile_ptr(src);
100	    ConvertForDequant<typename TileDataDst::DType, typename TileDataSrc::DType, dstRowStride, srcRowStride>(
101	        dstPtr, srcPtr, dstValidRows, dstValidCols);
102	    using T = typename TileDataPara::DType;
103	    __ubuf__ T* scalePtr = (__ubuf__ T*)__cce_get_tile_ptr(scale);
104	    __ubuf__ T* offsetPtr = (__ubuf__ T*)__cce_get_tile_ptr(offset);
105	    ApplyScaleAndOffset<T, dstRowStride, TileDataPara::RowStride>(
106	        dstPtr, scalePtr, offsetPtr, dstValidRows, dstValidCols);
107	}
108	
109	template <typename TileDataDst, typename TileDataSrc, typename TileDataPara>
110	PTO_INTERNAL void TDequantCheck(
111	    const TileDataDst& dst, const TileDataSrc& src, const TileDataPara& scale, const TileDataPara& offset)
112	{
113	    static_assert(
114	        std::is_same<typename TileDataDst::DType, float>::value ||
115	            std::is_same<typename TileDataDst::DType, float32_t>::value,
116	        "Fix: TDEQUANT dst tile currently supports float data type.");
117	    static_assert(
118	        std::is_same<typename TileDataPara::DType, float>::value ||
119	            std::is_same<typename TileDataPara::DType, float32_t>::value,
120	        "Fix: TDEQUANT parameter tile scale and offset currently support float data type.");
121	    static_assert(
122	        std::is_same<typename TileDataSrc::DType, int8_t>::value ||
123	            std::is_same<typename TileDataSrc::DType, int16_t>::value,
124	        "Fix: TDEQUANT source tile currently supports int8_t and int16_t data types.");
125	    static_assert(
126	        TileDataDst::isRowMajor && TileDataSrc::isRowMajor,
127	        "Fix: TDEQUANT src and dst tile only support row major layout.");
128	    unsigned dstValidRows = dst.GetValidRow();
129	    unsigned dstValidCols = dst.GetValidCol();
130	    PTO_ASSERT(
131	        src.GetValidRow() == dstValidRows && src.GetValidCol() == dstValidCols,
132	        "Fix: TDEQUANT source tile valid shape mismatch with dst tile valid shape.");
133	}
134	
135	template <typename TileDataDst, typename TileDataSrc, typename TileDataPara>
136	PTO_INTERNAL void TDEQUANT_IMPL(TileDataDst& dst, TileDataSrc& src, TileDataPara& scale, TileDataPara& offset)
137	{
138	    TDequantCheck<TileDataDst, TileDataSrc, TileDataPara>(dst, src, scale, offset);
139	    constexpr unsigned dstRowStride = TileDataDst::RowStride;
140	    constexpr unsigned srcRowStride = TileDataSrc::RowStride;
141	    constexpr unsigned scaleRowStride = TileDataPara::RowStride;
142	    TDequant<TileDataDst, TileDataSrc, TileDataPara, dstRowStride, srcRowStride, scaleRowStride>(
143	        dst.data(), src.data(), scale.data(), offset.data(), dst.GetValidRow(), dst.GetValidCol());
144	}
