11	/**
12	 * @file TCvt.hpp
13	 * @brief Type Conversion (TCVT) Implementation for NPU A2/A3 Architecture
14	 *
15	 * FILE ORGANIZATION (for easy navigation):
16	 * =======================================
17	 *
18	 * SUPPORTED CONVERSIONS (quick lookup):
19	 * ====================================
20	 * FP32:  -> FP16, FP32 (rounding only), BF16, I16, I32, I64
21	 * FP16:  -> FP32, I32, I16, I8, U8, S4 (int4b_t)
22	 * BF16:  -> FP32, I32
23	 * I16:   -> FP16, FP32
24	 * I32:   -> FP32, I16, I64, FP16 (deq)
25	 * I64:   -> FP32, I32
26	 * U8:    -> FP16
27	 * I8:    -> FP16
28	 * S4:    -> FP16
29	 *
30	 * 1. GenCastCall* helpers (lines ~20-360)
31	 *    - fp32 -> fp16/fp32/int64/int32/int16/bf16
32	 *    - fp16 -> int32/int16/int8/uint8
33	 *    - bf16 -> int32
34	 *    - int16/int32/int64 -> fp16/fp32
35	 *
36	 * 2. GenCastCallSpecialCases (lines ~360-450)
37	 *    - half<->fp32, bf16->fp32, int8/uint8->half
38	 *    - int64<->int32, int32->int16, int32->half (deq)
39	 *
40	 * 3. GenCastCall Dispatcher (lines ~450-530)
41	 *    - Compile-time type routing to the correct GenCastCall* helper
42	 *    - Overload with tmpPtr forwards scratch buffer to NonSatTorch paths
43	 *
44	 * 4. TCvtHead (lines ~540-600)
45	 *    - Processes aligned repeat blocks for main data region
46	 *    - Overload with tmpPtr passes scratch buffer through to GenCastCall
47	 *
48	 * 5. TCvt Kernel (lines ~610-700)
49	 *    - Handles aligned region and remainder with vector masking
50	 *    - Overload with TmpTileData uses user-supplied tile instead of TMP_UB_OFFSET
51	 *
52	 * 6. TCVT_IMPL (lines ~710-end)
53	 *    - High-level entry point computing repeat configuration
54	 *    - Overloads with TmpTileData mirror TSort32's with-tmp interface
55	 *
56	 * QUICK FIND: Search for the conversion function name (e.g., "GenCastCallFp32ToFp16")
57	 * or the dispatcher "GenCastCall" to locate the relevant section.
58	 */
59	
60	#ifndef TCVT_HPP
61	#define TCVT_HPP
62	
63	#include "common.hpp"
64	
65	namespace pto {
66	// ============================================================================
67	// Type Conversion Functions
68	// ============================================================================
69	// Specialized data type conversions with support for multiple rounding modes:
70	// RINT, ROUND, FLOOR, CEIL, TRUNC, ODD, NONE
71	// ============================================================================
72	inline namespace TCvtInternal {
73	// CTRL[59] controls saturation mode for FP to INT conversions:
74	// - 0 (ON):  Clamp to datatype range (e.g., 300.0f -> int8 = 127)
75	// - 1 (OFF): Truncate via bit masking (e.g., 300.0f -> int8 = 44 from 300 & 0xFF)
76	constexpr const int SAT_MODE_BIT = 59;
77	
78	// Temporary buffer size for non-saturation conversions (REPEAT_MAX * 256 bytes)
79	constexpr const size_t FP16_INT8_TEMP_BUFFER_SIZE = REPEAT_MAX * 256;
80	} // namespace TCvtInternal
81	
82	// PyTorch alignment for edge cases (inf, -inf, nan, overflow)
83	// 1 = PyTorch-compatible (uses NonSatTorch), 0 = standard (faster)
84	#define EDGE_CASE_ALIGN_ENABLE 1
85	
86	// FP32 -> FP16 conversion
87	template <typename TileDataD, typename TileDataS>
88	PTO_INTERNAL void GenCastCallFp32ToFp16(
89	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
90	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride)
91	{
92	    switch (static_cast<RoundMode>(mode)) {
93	        case RoundMode::CAST_RINT:
94	            vconv_f322f16r(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
95	            break;
96	        case RoundMode::CAST_ROUND:
97	            vconv_f322f16a(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
98	            break;
99	        case RoundMode::CAST_FLOOR:
100	            vconv_f322f16f(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
101	            break;
102	        case RoundMode::CAST_CEIL:
103	            vconv_f322f16c(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
104	            break;
105	        case RoundMode::CAST_TRUNC:
106	            vconv_f322f16z(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
107	            break;
108	        case RoundMode::CAST_ODD:
109	            vconv_f322f16o(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
110	            break;
111	        default:
