229	// FP32 -> INT16 conversion (PyTorch-compatible for inf/-inf)
230	// Two-step: fp32 -> int32 -> int16
231	template <typename TileDataD, typename TileDataS>
232	PTO_INTERNAL void GenCastCallFp32ToInt16_NonSatTorch(
233	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
234	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride,
235	    __ubuf__ int32_t* tempInt32Buf)
236	{
237	    set_ctrl(sbitset0(get_ctrl(), SAT_MODE_BIT)); // Turn on saturation for int32 conversion
238	    switch (static_cast<RoundMode>(mode)) {
239	        case RoundMode::CAST_RINT:
240	            vconv_f322s32r(
241	                tempInt32Buf, src, repeatNum, srcBlockStride, srcBlockStride, srcRepeatStride, srcRepeatStride);
242	            break;
243	        case RoundMode::CAST_ROUND:
244	            vconv_f322s32a(
245	                tempInt32Buf, src, repeatNum, srcBlockStride, srcBlockStride, srcRepeatStride, srcRepeatStride);
246	            break;
247	        case RoundMode::CAST_FLOOR:
248	            vconv_f322s32f(
249	                tempInt32Buf, src, repeatNum, srcBlockStride, srcBlockStride, srcRepeatStride, srcRepeatStride);
250	            break;
251	        case RoundMode::CAST_CEIL:
252	            vconv_f322s32c(
253	                tempInt32Buf, src, repeatNum, srcBlockStride, srcBlockStride, srcRepeatStride, srcRepeatStride);
254	            break;
255	        case RoundMode::CAST_TRUNC:
256	            vconv_f322s32z(
257	                tempInt32Buf, src, repeatNum, srcBlockStride, srcBlockStride, srcRepeatStride, srcRepeatStride);
258	            break;
259	        default:
260	            vconv_f322s32z(
261	                tempInt32Buf, src, repeatNum, srcBlockStride, srcBlockStride, srcRepeatStride, srcRepeatStride);
262	            break;
263	    }
264	
265	    pipe_barrier(PIPE_V);
266	    set_ctrl(sbitset1(get_ctrl(), SAT_MODE_BIT));
267	    vconv_s322s16(dst, tempInt32Buf, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
268	}
