362	// FP16 -> INT16 conversion (PyTorch-compatible for inf/-inf): fp16 -> int32 -> int16
363	//
364	// Per-repeat hardware element capacity:
365	//   int32 ops (vconv_f162s32*, vconv_s322s16) : 64
366	//   fp16/int16 native ops                     : 128
367	//
368	// Strategy: iterate row-by-row, splitting each row into sub-chunks of <=64 elements so every
369	// instruction stays within the int32 capacity.  Each sub-chunk sets its own continuous mask,
370	// runs one fp16->int32 repeat and one int32->int16 repeat.
371	//
372	// Params:
373	//   repeatNum        logical repeats (rows).
374	//   src/dstRepeatStride  block-stride between rows (in src fp16 / dst int16 blocks).
375	//   numElemsPerRow   valid elements per row.  0 means "head default" (= 128);
376	//                    tail callers pass numRemainPerLine in [1, 128].
377	//
378	// Caller contexts:
379	//   HEAD (TCvtHead): numElemsPerRow=0, caller mask full.
380	//   TAIL (TCvtTail): numElemsPerRow=numRemainPerLine; caller's mask is overridden per sub-chunk.
381	template <typename TileDataD, typename TileDataS>
382	PTO_INTERNAL void GenCastCallFp16ToInt16_NonSatTorch(
383	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
384	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride,
385	    __ubuf__ int32_t* tempInt32Buf, uint16_t numElemsPerRow = 0)
386	{
387	    constexpr uint16_t fp16ElemsPerBlock = BLOCK_BYTE_SIZE / sizeof(half);     // 16
388	    constexpr uint16_t int16ElemsPerBlock = BLOCK_BYTE_SIZE / sizeof(int16_t); // 16
389	    constexpr uint16_t maxChunkElems = 64;                                     // int32 hw cap per repeat
390	
391	    // elemsPerRow: head path leaves numElemsPerRow=0 → full 128; tail forwards actual count.
392	    const uint16_t elemsPerRow = (numElemsPerRow == 0) ? static_cast<uint16_t>(128) : numElemsPerRow;
393	    const uint16_t numSubChunks = (elemsPerRow + maxChunkElems - 1) / maxChunkElems; // 1 or 2
394	    const uint16_t lastChunkMask = elemsPerRow - (numSubChunks - 1) * maxChunkElems; // [1, 64]
395	
396	    for (uint16_t r = 0; r < repeatNum; r++) {
397	        __ubuf__ half* rowSrc = src + static_cast<uint32_t>(r) * srcRepeatStride * fp16ElemsPerBlock;
398	        __ubuf__ int16_t* rowDst = dst + static_cast<uint32_t>(r) * dstRepeatStride * int16ElemsPerBlock;
399	
400	        for (uint16_t c = 0; c < numSubChunks; c++) {
401	            __ubuf__ int16_t* chunkDst = rowDst + static_cast<uint32_t>(c) * maxChunkElems;
402	            __ubuf__ half* chunkSrc = rowSrc + static_cast<uint32_t>(c) * maxChunkElems;
403	            const uint16_t chunkMask = (c + 1 == numSubChunks) ? lastChunkMask : maxChunkElems;
404	
405	            SetContinuousMask(chunkMask);
406	
407	            // Step 1: fp16 -> int32 with saturation (clamps inf/overflow into int32 range).
408	            set_ctrl(sbitset0(get_ctrl(), SAT_MODE_BIT));
409	            GenCastCallFp16ToInt32ByRoundMode(tempInt32Buf, chunkSrc, 1, mode, srcBlockStride, srcBlockStride, 8, 8);
410	            pipe_barrier(PIPE_V);
411	
412	            // Step 2: int32 -> int16 (non-saturating wrap-around — PyTorch low-16-bit semantics).
413	            set_ctrl(sbitset1(get_ctrl(), SAT_MODE_BIT));
414	            vconv_s322s16(chunkDst, tempInt32Buf, 1, dstBlockStride, srcBlockStride, 8, 8);
415	            pipe_barrier(PIPE_V);
416	        }
417	    }
418	
419	    // Leave mask in a predictable (full) state so downstream vector ops are unaffected.
420	    set_vector_mask(-1, -1);
421	}
