453	// FP16 -> INT8 conversion, PyTorch-compatible for inf/-inf/overflow (wrap-around semantics).
454	// Pipeline: fp16 --sat--> int32 --narrow--> int16 --AND 0xFF--> int16 --> fp16 --> int8.
455	// (vand only accepts short* on this arch, hence the int32->int16 narrow before masking.)
456	//
457	// Per-repeat hardware element capacity:
458	//   int32 ops (vconv_f162s32*, vconv_s322s16) : 64
459	//   fp16/int16/int8 ops (vand, vconv_s162f16, vconv_f162s8z) : 128
460	//
461	// Strategy: iterate row-by-row, and within each row split into sub-chunks of <=64 elements so
462	// every instruction below stays within the int32 capacity.  All vector ops use repeat=1 with
463	// pipe_barrier between steps — correctness-first, immune to multi-repeat in-place hazards.
464	//
465	// Params:
466	//   repeatNum        logical repeats (rows).
467	//   src/dstRepeatStride  block-stride between rows (in src fp16 / dst int8 blocks).
468	//   numElemsPerRow   valid elements per row.  0 means "head default" (= 128);
469	//                    tail callers pass numRemainPerLine in [1, 128].
470	//
471	// Caller contexts:
472	//   HEAD (TCvtHead): numElemsPerRow=0, caller mask full.
473	//   TAIL (TCvtTail): numElemsPerRow=numRemainPerLine; caller's mask is overridden per sub-chunk.
474	//
475	// Temp buffer layout (256 B, reused every sub-chunk):
476	//   bytes   [0..127]  : int32 (lo 32) then int16 after in-place narrow (same 64 lanes)
477	//   bytes   [128..255]: mask of 0x00FF, then fp16 step-5 output
478	// (Upper 128 bytes of the int32 region are freed by the narrow and repurposed as scratch.)
479	//
480	// NOTE: src must NOT be reused as scratch — the saturation test kernel invokes TCVT three times
481	// on the same srcTile (ON/OFF/default), so clobbering src would corrupt later invocations.
482	template <typename TileDataD, typename TileDataS>
483	PTO_INTERNAL void GenCastCallFp16ToInt8_NonSatTorch(
484	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
485	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride,
486	    __ubuf__ int32_t* tempInt32Buf, uint16_t numElemsPerRow)
487	{
488	    constexpr uint16_t fp16ElemsPerBlock = BLOCK_BYTE_SIZE / sizeof(half);   // 16
489	    constexpr uint16_t int8ElemsPerBlock = BLOCK_BYTE_SIZE / sizeof(int8_t); // 32
490	    constexpr uint16_t maxChunkElems = 64;                                   // int32 hw cap per repeat
491	
492	    // Temp aliases over the shared 256-byte tempInt32Buf.
493	    //   tempAndBuf   : bytes [0..127]   -- int16 view (overlays the int32 lanes after narrow).
494	    //   tempMaskBuf  : bytes [128..255] -- scratch for the 0x00FF mask and step-5 fp16 output.
495	    __ubuf__ int16_t* tempAndBuf = (__ubuf__ int16_t*)tempInt32Buf;
496	    __ubuf__ int16_t* tempMaskBuf = tempAndBuf + maxChunkElems;
497	    __ubuf__ half* tempFp16Out = (__ubuf__ half*)tempMaskBuf;
498	
499	    // elemsPerRow: head path leaves numElemsPerRow=0 → full 128; tail forwards actual count.
500	    const uint16_t elemsPerRow = (numElemsPerRow == 0) ? static_cast<uint16_t>(128) : numElemsPerRow;
501	    const uint16_t numSubChunks = (elemsPerRow + maxChunkElems - 1) / maxChunkElems; // 1 or 2
502	    const uint16_t lastChunkMask = elemsPerRow - (numSubChunks - 1) * maxChunkElems; // [1, 64]
503	
504	    for (uint16_t r = 0; r < repeatNum; r++) {
505	        __ubuf__ half* rowSrc = src + static_cast<uint32_t>(r) * srcRepeatStride * fp16ElemsPerBlock;
506	        __ubuf__ int8_t* rowDst = dst + static_cast<uint32_t>(r) * dstRepeatStride * int8ElemsPerBlock;
507	
508	        for (uint16_t c = 0; c < numSubChunks; c++) {
509	            __ubuf__ half* chunkSrc = rowSrc + static_cast<uint32_t>(c) * maxChunkElems;
510	            __ubuf__ int8_t* chunkDst = rowDst + static_cast<uint32_t>(c) * maxChunkElems;
511	            const uint16_t chunkMask = (c + 1 == numSubChunks) ? lastChunkMask : maxChunkElems;
512	
513	            SetContinuousMask(chunkMask);
514	
515	            // Step 1: fp16 -> int32 with saturation (clamps inf/overflow into int32 range).
516	            set_ctrl(sbitset0(get_ctrl(), SAT_MODE_BIT));
517	            GenCastCallFp16ToInt32ByRoundMode(tempInt32Buf, chunkSrc, 1, mode, srcBlockStride, srcBlockStride, 8, 8);
518	            pipe_barrier(PIPE_V);
519	
520	            // Switch to non-saturating (wrap-around) mode for the remaining narrowing stages —
521	            // this is what produces PyTorch's low-8-bit behaviour on overflow.
522	            set_ctrl(sbitset1(get_ctrl(), SAT_MODE_BIT));
523	
524	            // Step 2: int32 -> int16, in-place over the same 64 lanes.
525	            vconv_s322s16(tempAndBuf, tempInt32Buf, 1, srcBlockStride, srcBlockStride, 8, 8);
526	            pipe_barrier(PIPE_V);
527	
528	            // Step 3: broadcast 0x00FF mask into the upper scratch region.
529	            vector_dup(tempMaskBuf, static_cast<int16_t>(255), 1, srcBlockStride, srcBlockStride, 8, 8);
530	            pipe_barrier(PIPE_V);
531	
532	            // Step 4: keep low 8 bits (int16 & 0xFF) in place.
533	            vand(tempAndBuf, tempAndBuf, tempMaskBuf, 1, srcBlockStride, srcBlockStride, srcBlockStride, 8, 8, 8);
534	            pipe_barrier(PIPE_V);
535	
536	            // Step 5: int16 -> fp16 into the mask's old slot (the mask has been consumed).
537	            vconv_s162f16(tempFp16Out, tempAndBuf, 1, srcBlockStride, srcBlockStride, 8, 8);
538	            pipe_barrier(PIPE_V);
539	
540	            // Step 6: fp16 -> int8 into the caller's destination for this sub-chunk.
541	            vconv_f162s8z(chunkDst, tempFp16Out, 1, dstBlockStride, srcBlockStride, 8, 8);
542	            pipe_barrier(PIPE_V);
543	        }
544	    }
545	
546	    // Leave mask in a predictable (full) state so downstream vector ops are unaffected.
547	    set_vector_mask(-1, -1);
548	}
