550	// FP16 -> UINT8 conversion
551	template <typename TileDataD, typename TileDataS>
552	PTO_INTERNAL void GenCastCallFp16ToUint8(
553	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
554	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride)
555	{
556	    switch (static_cast<RoundMode>(mode)) {
557	        case RoundMode::CAST_RINT:
558	            vconv_f162u8r(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
559	            break;
560	        case RoundMode::CAST_ROUND:
561	            vconv_f162u8a(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
562	            break;
563	        case RoundMode::CAST_FLOOR:
564	            vconv_f162u8f(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
565	            break;
566	        case RoundMode::CAST_CEIL:
567	            vconv_f162u8c(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
568	            break;
569	        case RoundMode::CAST_TRUNC:
570	            vconv_f162u8z(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
571	            break;
572	        default:
573	            vconv_f162u8z(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
574	            break;
575	    }
