733	// Special case conversions: half<->fp32, bf16<->fp32, int/uint 8<->half,
734	// int32<->int64, int32<->int16, int32->half (deq)
735	template <typename TileDataD, typename TileDataS>
736	PTO_INTERNAL void GenCastCallSpecialCases(
737	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
738	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride)
739	{
740	    if constexpr (
741	        std::is_same<typename TileDataD::DType, float>::value &&
742	        std::is_same<typename TileDataS::DType, half>::value) { // half to fp32
743	        vconv_f162f32(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
744	    } else if constexpr (
745	        std::is_same<typename TileDataD::DType, float>::value &&
746	        std::is_same<typename TileDataS::DType, bfloat16_t>::value) { // bfloat16 to float
747	        vconv_bf162f32(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
748	    } else if constexpr (
749	        std::is_same<typename TileDataD::DType, half>::value &&
750	        std::is_same<typename TileDataS::DType, uint8_t>::value) { // uint8 to half
751	        vconv_u82f16(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
752	    } else if constexpr (
753	        std::is_same<typename TileDataD::DType, half>::value &&
754	        std::is_same<typename TileDataS::DType, int8_t>::value) { // int8 to half
755	        vconv_s82f16(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
756	    } else if constexpr (
757	        std::is_same<typename TileDataD::DType, float>::value &&
758	        std::is_same<typename TileDataS::DType, int16_t>::value) { // int16 to float32
759	        vconv_s162f32(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
760	    } else if constexpr (
761	        std::is_same<typename TileDataD::DType, int32_t>::value &&
762	        std::is_same<typename TileDataS::DType, int64_t>::value) { // int64 to int32
763	        vconv_s642s32(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
764	    } else if constexpr (
765	        std::is_same<typename TileDataD::DType, int64_t>::value &&
766	        std::is_same<typename TileDataS::DType, int32_t>::value) { // int32 to int64
767	        vconv_s322s64(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
768	    } else if constexpr (
769	        std::is_same<typename TileDataD::DType, int16_t>::value &&
770	        std::is_same<typename TileDataS::DType, int32_t>::value) { // int32 to int16
771	        vconv_s322s16(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
772	    } else if constexpr (
773	        std::is_same<typename TileDataD::DType, half>::value &&
774	        std::is_same<typename TileDataS::DType, int32_t>::value) { // int32 to half
775	        set_deqscale(static_cast<half>(1.0));
776	        pipe_barrier(PIPE_V);
777	        vconv_deq(dst, src, repeatNum, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
778	    }
779	}
