782	// Type Conversion Dispatcher
783	// ============================================================================
784	// The trailing `numElemsPerRow` parameter is only consumed by NonSatTorch paths that need
785	// explicit sub-chunk splitting (currently fp16 -> int8).  TCvtTail forwards its
786	// numRemainPerLine as this argument so the NonSatTorch path can split rows wider than the
787	// int32 hardware capacity (64 elements) into multiple sub-chunks.  TCvtHead leaves it at the
788	// default 0 which the NonSatTorch path interprets as "full logical repeat" (= 128 elements).
789	template <typename TileDataD, typename TileDataS>
790	AICORE void GenCastCall(
791	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
792	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride,
793	    uint16_t /*numElemsPerRow*/ = 0)
794	{
795	    if constexpr (
796	        std::is_same<typename TileDataD::DType, half>::value && std::is_same<typename TileDataS::DType, float>::value) {
797	        GenCastCallFp32ToFp16<TileDataD, TileDataS>(
798	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
799	    } else if constexpr (
800	        std::is_same<typename TileDataD::DType, float>::value &&
801	        std::is_same<typename TileDataS::DType, float>::value) { // fp32 to fp32
802	        GenCastCallFp32ToFp32<TileDataD, TileDataS>(
803	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
804	    } else if constexpr (
805	        std::is_same<typename TileDataD::DType, int64_t>::value &&
806	        std::is_same<typename TileDataS::DType, float>::value) { // fp32 to int64
807	        GenCastCallFp32ToInt64<TileDataD, TileDataS>(
808	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
809	    } else if constexpr (
810	        std::is_same<typename TileDataD::DType, int32_t>::value &&
811	        std::is_same<typename TileDataS::DType, float>::value) { // fp32 to int32
812	        GenCastCallFp32ToInt32<TileDataD, TileDataS>(
813	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
814	    } else if constexpr (
815	        std::is_same<typename TileDataD::DType, int16_t>::value &&
816	        std::is_same<typename TileDataS::DType, float>::value) { // fp32 to int16
817	        GenCastCallFp32ToInt16<TileDataD, TileDataS>(
818	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
819	    } else if constexpr (
820	        std::is_same<typename TileDataD::DType, bfloat16_t>::value &&
821	        std::is_same<typename TileDataS::DType, float>::value) { // fp32 to bf16
822	        GenCastCallFp32ToBf16<TileDataD, TileDataS>(
823	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
824	    } else if constexpr (
825	        std::is_same<typename TileDataD::DType, int32_t>::value &&
826	        std::is_same<typename TileDataS::DType, half>::value) { // half to int32
827	        GenCastCallFp16ToInt32<TileDataD, TileDataS>(
828	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
829	    } else if constexpr (
830	        std::is_same<typename TileDataD::DType, int16_t>::value &&
831	        std::is_same<typename TileDataS::DType, half>::value) { // half to int16
832	        GenCastCallFp16ToInt16<TileDataD, TileDataS>(
833	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
834	    } else if constexpr (
835	        std::is_same<typename TileDataD::DType, int8_t>::value &&
836	        std::is_same<typename TileDataS::DType, half>::value) { // half to int8
837	        GenCastCallFp16ToInt8<TileDataD, TileDataS>(
838	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
839	    } else if constexpr (
840	        std::is_same<typename TileDataD::DType, uint8_t>::value &&
841	        std::is_same<typename TileDataS::DType, half>::value) { // half to uint8
842	        GenCastCallFp16ToUint8<TileDataD, TileDataS>(
843	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
844	    } else if constexpr (
845	        std::is_same<typename TileDataD::DType, int4b_t>::value &&
846	        std::is_same<typename TileDataS::DType, half>::value) { // half to int4
847	        GenCastCallFp16ToS4<TileDataD, TileDataS>(
848	            (__ubuf__ void*)dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride,
849	            srcRepeatStride);
850	    } else if constexpr (
851	        std::is_same<typename TileDataD::DType, half>::value &&
852	        std::is_same<typename TileDataS::DType, int4b_t>::value) { // int4 to half
853	        GenCastCallS4ToFp16<TileDataD, TileDataS>(
854	            dst, (__ubuf__ void*)src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride,
855	            srcRepeatStride);
856	    } else if constexpr (
857	        std::is_same<typename TileDataD::DType, int32_t>::value &&
858	        std::is_same<typename TileDataS::DType, bfloat16_t>::value) { // bfloat16 to int32
859	        GenCastCallBf16ToInt32<TileDataD, TileDataS>(
860	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
861	    } else if constexpr (
862	        std::is_same<typename TileDataD::DType, half>::value &&
863	        std::is_same<typename TileDataS::DType, int16_t>::value) { // int16 to half
864	        GenCastCallInt16ToFp16<TileDataD, TileDataS>(
865	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
866	    } else if constexpr (
867	        std::is_same<typename TileDataD::DType, float>::value &&
868	        std::is_same<typename TileDataS::DType, int32_t>::value) { // int32 to float
869	        GenCastCallInt32ToFp32<TileDataD, TileDataS>(
870	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
871	    } else if constexpr (
872	        std::is_same<typename TileDataD::DType, float>::value &&
873	        std::is_same<typename TileDataS::DType, int64_t>::value) { // int64 to float
874	        GenCastCallInt64ToFp32<TileDataD, TileDataS>(
875	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
876	    } else {
877	        GenCastCallSpecialCases<TileDataD, TileDataS>(
878	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
879	    }
880	}
