882	// GenCastCall overload with explicit temporary buffer pointer.
883	// Mirrors the no-tmp GenCastCall but forwards tmpPtr to NonSatTorch paths
884	// instead of using the fixed TMP_UB_OFFSET global scratch area.
885	//
886	// The trailing `numElemsPerRow` parameter (default 0) is forwarded to NonSatTorch paths that
887	// need explicit sub-chunk splitting.  TCvtTail passes numRemainPerLine here; TCvtHead leaves
888	// it at 0 (interpreted as "full logical repeat" by the fp16 -> int8 NonSatTorch path).
889	template <typename TileDataD, typename TileDataS>
890	AICORE void GenCastCall(
891	    __ubuf__ typename TileDataD::DType* dst, __ubuf__ typename TileDataS::DType* src, uint8_t repeatNum, RoundMode mode,
892	    uint16_t dstBlockStride, uint16_t srcBlockStride, uint16_t dstRepeatStride, uint16_t srcRepeatStride,
893	    __ubuf__ int32_t* tmpPtr, uint16_t numElemsPerRow = 0)
894	{
895	    if constexpr (
896	        std::is_same<typename TileDataD::DType, int16_t>::value &&
897	        std::is_same<typename TileDataS::DType, float>::value) { // fp32 to int16
898	        bool isSatOn = (get_ctrl() & (1ULL << SAT_MODE_BIT)) == 0;
899	#if EDGE_CASE_ALIGN_ENABLE
900	        if (!isSatOn) {
901	            GenCastCallFp32ToInt16_NonSatTorch<TileDataD, TileDataS>(
902	                dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride, tmpPtr);
903	        } else {
904	            GenCastCallFp32ToInt16<TileDataD, TileDataS>(
905	                dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
906	        }
907	#else
908	        GenCastCallFp32ToInt16<TileDataD, TileDataS>(
909	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
910	#endif
911	    } else if constexpr (
912	        std::is_same<typename TileDataD::DType, int16_t>::value &&
913	        std::is_same<typename TileDataS::DType, half>::value) { // half to int16
914	        bool isSatOn = (get_ctrl() & (1ULL << SAT_MODE_BIT)) == 0;
915	#if EDGE_CASE_ALIGN_ENABLE
916	        if (!isSatOn) {
917	            GenCastCallFp16ToInt16_NonSatTorch<TileDataD, TileDataS>(
918	                dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride, tmpPtr,
919	                numElemsPerRow);
920	        } else {
921	            GenCastCallFp16ToInt16<TileDataD, TileDataS>(
922	                dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
923	        }
924	#else
925	        GenCastCallFp16ToInt16<TileDataD, TileDataS>(
926	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
927	#endif
928	    } else if constexpr (
929	        std::is_same<typename TileDataD::DType, int8_t>::value &&
930	        std::is_same<typename TileDataS::DType, half>::value) { // half to int8
931	        bool isSatOn = (get_ctrl() & (1ULL << SAT_MODE_BIT)) == 0;
932	#if EDGE_CASE_ALIGN_ENABLE
933	        if (!isSatOn) {
934	            GenCastCallFp16ToInt8_NonSatTorch<TileDataD, TileDataS>(
935	                dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride, tmpPtr,
936	                numElemsPerRow);
937	        } else {
938	            GenCastCallFp16ToInt8<TileDataD, TileDataS>(
939	                dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
940	        }
941	#else
942	        GenCastCallFp16ToInt8<TileDataD, TileDataS>(
943	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
944	#endif
945	    } else {
946	        GenCastCall<TileDataD, TileDataS>(
947	            dst, src, repeatNum, mode, dstBlockStride, srcBlockStride, dstRepeatStride, srcRepeatStride);
948	    }
949	}
