951	// ============================================================================
952	// Tile Conversion Helper: Process Main Data Block
953	// ============================================================================
954	// TCvtHead processes the primary aligned portion of data in complete repeat units.
955	// This handles data that fits evenly into repeat boundaries.
956	//
957	// @param dstPtr: Destination buffer pointer
958	// @param srcPtr: Source buffer pointer
959	// @param mode: Rounding mode for type conversions
960	// @param numRepeatPerLine: Number of complete repeats per line
961	// @param validRow: Number of valid rows to process
962	// @param elementsPerRepeat: Number of elements per repeat unit
963	// @param dstRepeatStride: Stride between repeats in destination
964	// @param srcRepeatStride: Stride between repeats in source
965	template <typename TileDataD, typename TileDataS, unsigned SS, unsigned DS>
966	PTO_INST void TCvtHead(
967	    __ubuf__ typename TileDataD::DType* dstPtr, __ubuf__ typename TileDataS::DType* srcPtr, RoundMode mode,
968	    unsigned numRepeatPerLine, unsigned validRow, unsigned elementsPerRepeat, unsigned dstRepeatStride,
969	    unsigned srcRepeatStride)
970	{
971	    unsigned numLoop = numRepeatPerLine / REPEAT_MAX;
972	    unsigned remainAfterLoop = numRepeatPerLine % REPEAT_MAX;
973	    for (uint32_t i = 0; i < validRow; i++) {
974	        if (numLoop > 0) {
975	            for (uint32_t j = 0; j < numLoop; j++) {
976	                GenCastCall<TileDataD, TileDataS>(
977	                    dstPtr + i * DS + j * elementsPerRepeat * REPEAT_MAX,
978	                    srcPtr + i * SS + j * elementsPerRepeat * REPEAT_MAX, (uint8_t)REPEAT_MAX, mode, 1, 1,
979	                    (uint16_t)dstRepeatStride, (uint16_t)srcRepeatStride);
980	            }
981	        }
982	        if (remainAfterLoop > 0) {
983	            GenCastCall<TileDataD, TileDataS>(
984	                dstPtr + i * DS + numLoop * elementsPerRepeat * REPEAT_MAX,
985	                srcPtr + i * SS + numLoop * elementsPerRepeat * REPEAT_MAX, (uint8_t)remainAfterLoop, mode, 1, 1,
986	                (uint16_t)dstRepeatStride, (uint16_t)srcRepeatStride);
987	        }
988	    }
989	}
