991	// TCvtHead overload with explicit temporary buffer pointer (forwarded to GenCastCall with tmp).
992	template <typename TileDataD, typename TileDataS, unsigned SS, unsigned DS>
993	PTO_INST void TCvtHead(
994	    __ubuf__ typename TileDataD::DType* dstPtr, __ubuf__ typename TileDataS::DType* srcPtr, RoundMode mode,
995	    unsigned numRepeatPerLine, unsigned validRow, unsigned elementsPerRepeat, unsigned dstRepeatStride,
996	    unsigned srcRepeatStride, __ubuf__ int32_t* tmpPtr)
997	{
998	    unsigned numLoop = numRepeatPerLine / REPEAT_MAX;
999	    unsigned remainAfterLoop = numRepeatPerLine % REPEAT_MAX;
1000	    for (uint32_t i = 0; i < validRow; i++) {
1001	        if (numLoop > 0) {
1002	            for (uint32_t j = 0; j < numLoop; j++) {
1003	                GenCastCall<TileDataD, TileDataS>(
1004	                    dstPtr + i * DS + j * elementsPerRepeat * REPEAT_MAX,
1005	                    srcPtr + i * SS + j * elementsPerRepeat * REPEAT_MAX, (uint8_t)REPEAT_MAX, mode, 1, 1,
1006	                    (uint16_t)dstRepeatStride, (uint16_t)srcRepeatStride, tmpPtr);
1007	            }
1008	        }
1009	        if (remainAfterLoop > 0) {
