1011	                dstPtr + i * DS + numLoop * elementsPerRepeat * REPEAT_MAX,
1012	                srcPtr + i * SS + numLoop * elementsPerRepeat * REPEAT_MAX, (uint8_t)remainAfterLoop, mode, 1, 1,
1013	                (uint16_t)dstRepeatStride, (uint16_t)srcRepeatStride, tmpPtr);
1014	        }
1015	    }
