1021	
1022	template <bool NeedSetCtrl>
1023	PTO_INST bool ApplySatMode(SaturationMode satMode)
1024	{
1025	    if constexpr (NeedSetCtrl) {
1026	        uint64_t originalCtrl = get_ctrl();
1027	        bool originalSatMode = (originalCtrl & (1ULL << SAT_MODE_BIT)) == 0;
1028	        if (satMode == SaturationMode::OFF) {
1029	            set_ctrl(sbitset1(get_ctrl(), SAT_MODE_BIT));
1030	        } else {
1031	            set_ctrl(sbitset0(get_ctrl(), SAT_MODE_BIT));
1032	        }
1033	        return originalSatMode;
1034	    }
1035	    return false;
1036	}
1037	
1038	template <bool NeedSetCtrl>
1039	PTO_INST void RestoreSatMode(bool originalSatMode)
1040	{
1041	    if constexpr (NeedSetCtrl) {
1042	        if (originalSatMode) {
1043	            set_ctrl(sbitset0(get_ctrl(), SAT_MODE_BIT));
1044	        } else {
1045	            set_ctrl(sbitset1(get_ctrl(), SAT_MODE_BIT));
1046	        }
1047	    }
1048	}
