1050	// ============================================================================
1051	// Tile Conversion Helper: Process Remainder Data Block
1052	// ============================================================================
1053	// TCvtTail processes the remainder (unaligned) portion of data that doesn't
1054	// fit evenly into repeat boundaries, using vector masking.
1055	//
1056	// numRemainPerLine is forwarded as the trailing `numElemsPerRow` arg of GenCastCall so that
1057	// NonSatTorch paths which need explicit sub-chunk splitting (fp16 -> int8) can honor the valid
1058	// column count even when it exceeds the int32 hardware capacity (64 elements) per repeat.
1059	template <typename TileDataD, typename TileDataS, unsigned SS, unsigned DS, typename... Args>
1060	PTO_INST void TCvtTail(
1061	    __ubuf__ typename TileDataD::DType* dstPtr, __ubuf__ typename TileDataS::DType* srcPtr, RoundMode mode,
1062	    unsigned validRow, unsigned numRemainPerLine, Args... args)
1063	{
1064	    constexpr unsigned dstNElemPerBlock = BLOCK_BYTE_SIZE / sizeof(typename TileDataD::DType);
1065	    constexpr unsigned srcNElemPerBlock = BLOCK_BYTE_SIZE / sizeof(typename TileDataS::DType);
1066	    unsigned numLoop = validRow / REPEAT_MAX;
1067	    unsigned remainAfterLoop = validRow % REPEAT_MAX;
1068	    SetContinuousMask(numRemainPerLine);
1069	    const uint16_t numElemsPerRow = static_cast<uint16_t>(numRemainPerLine);
1070	    if (numLoop > 0) {
1071	        for (uint32_t j = 0; j < numLoop; j++) {
1072	            GenCastCall<TileDataD, TileDataS>(
1073	                dstPtr + j * DS * REPEAT_MAX, srcPtr + j * SS * REPEAT_MAX, (uint8_t)REPEAT_MAX, mode, 1, 1,
1074	                (uint16_t)DS / dstNElemPerBlock, (uint16_t)SS / srcNElemPerBlock, args..., numElemsPerRow);
1075	        }
1076	    }
1077	    if (remainAfterLoop > 0) {
1078	        GenCastCall<TileDataD, TileDataS>(
1079	            dstPtr + numLoop * DS * REPEAT_MAX, srcPtr + numLoop * SS * REPEAT_MAX, (uint8_t)remainAfterLoop, mode, 1,
1080	            1, (uint16_t)DS / dstNElemPerBlock, (uint16_t)SS / srcNElemPerBlock, args..., numElemsPerRow);
1081	    }
1082	    set_vector_mask(-1, -1);
1083	}
