1085	// ============================================================================
1086	// Core Tile Conversion Kernel
1087	// ============================================================================
1088	// TCvt orchestrates the complete tile conversion process by handling both:
1089	//   1. Aligned region: Complete repeat units processed via TCvtHead
1090	//   2. Remainder region: Partial repeats processed with vector masking
1091	//
1092	// Template parameters:
1093	//   SS: Source row stride
1094	//   DS: Destination row stride
1095	//
1096	// @param dst: Destination tile (output) - contains data after conversion
1097	// @param src: Source tile (input) - contains original data to be converted
1098	// @param mode: Rounding mode (RINT/ROUND/FLOOR/CEIL/TRUNC/NONE/ODD)
1099	// @param satMode: Saturation mode for float-to-int conversions:
1100	//                 ON  = Clamp to datatype range [min, max]
1101	//                 OFF = Convert to int64, extract least significant N bits
1102	// @param numRepeatPerLine: Number of complete repeats per line
1103	// @param numRemainPerLine: Remaining elements per line (not aligned to repeat)
1104	// @param validRow: Number of rows containing valid data
1105	// @param elementsPerRepeat: Number of elements per repeat operation
1106	// @param dstRepeatStride: Stride between repeats in destination buffer
1107	// @param srcRepeatStride: Stride between repeats in source buffer
1108	template <typename TileDataD, typename TileDataS, unsigned SS, unsigned DS, bool NeedSetCtrl>
1109	__tf__ AICORE void TCvt(
1110	    typename TileDataD::TileDType __out__ dst, typename TileDataS::TileDType __in__ src, RoundMode mode,
1111	    SaturationMode satMode, unsigned numRepeatPerLine, unsigned numRemainPerLine, unsigned validRow,
1112	    unsigned elementsPerRepeat, unsigned dstRepeatStride, unsigned srcRepeatStride)
1113	{
1114	    bool originalSatMode = ApplySatMode<NeedSetCtrl>(satMode);
1115	
1116	    __ubuf__ typename TileDataD::DType* dstPtr = (__ubuf__ typename TileDataD::DType*)__cce_get_tile_ptr(dst);
1117	    __ubuf__ typename TileDataS::DType* srcPtr = (__ubuf__ typename TileDataS::DType*)__cce_get_tile_ptr(src);
1118	
1119	    if (numRepeatPerLine > 0) {
1120	        TCvtHead<TileDataD, TileDataS, SS, DS>(
1121	            dstPtr, srcPtr, mode, numRepeatPerLine, validRow, elementsPerRepeat, dstRepeatStride, srcRepeatStride);
1122	    }
1123	    dstPtr += numRepeatPerLine * elementsPerRepeat;
1124	    srcPtr += numRepeatPerLine * elementsPerRepeat;
1125	
1126	    if (numRemainPerLine > 0) {
1127	        TCvtTail<TileDataD, TileDataS, SS, DS>(dstPtr, srcPtr, mode, validRow, numRemainPerLine);
1128	    }
1129	
1130	    RestoreSatMode<NeedSetCtrl>(originalSatMode);
1131	}
