1136	template <typename TileDataD, typename TileDataS, typename TmpTileData, unsigned SS, unsigned DS, bool NeedSetCtrl>
1137	__tf__ AICORE void TCvt(
1138	    typename TileDataD::TileDType __out__ dst, typename TileDataS::TileDType __in__ src,
1139	    typename TmpTileData::TileDType __in__ tmp, RoundMode mode, SaturationMode satMode, unsigned numRepeatPerLine,
1140	    unsigned numRemainPerLine, unsigned validRow, unsigned elementsPerRepeat, unsigned dstRepeatStride,
1141	    unsigned srcRepeatStride)
1142	{
