1144	
1145	    __ubuf__ typename TileDataD::DType* dstPtr = (__ubuf__ typename TileDataD::DType*)__cce_get_tile_ptr(dst);
1146	    __ubuf__ typename TileDataS::DType* srcPtr = (__ubuf__ typename TileDataS::DType*)__cce_get_tile_ptr(src);
1147	    __ubuf__ int32_t* tmpPtr = (__ubuf__ int32_t*)__cce_get_tile_ptr(tmp);
1148	
1149	    if (numRepeatPerLine > 0) {
1150	        TCvtHead<TileDataD, TileDataS, SS, DS>(
1151	            dstPtr, srcPtr, mode, numRepeatPerLine, validRow, elementsPerRepeat, dstRepeatStride, srcRepeatStride,
