1164	// ============================================================================
1165	// TCVT Helper: Compute Repeat Configuration
1166	// ============================================================================
1167	// Computes repeat stride and element count based on source/destination types.
1168	// Handles int4b_t packing (2 elements per byte) as a special case.
1169	template <typename TileDataD, typename TileDataS>
1170	PTO_INTERNAL void ComputeTCvtRepeatConfig(
1171	    unsigned& elementsPerRepeat, unsigned& dstRepeatStride, unsigned& srcRepeatStride)
1172	{
1173	    constexpr bool isDstInt4 = std::is_same<typename TileDataD::DType, int4b_t>::value;
1174	    constexpr bool isSrcInt4 = std::is_same<typename TileDataS::DType, int4b_t>::value;
1175	
1176	    if constexpr (isDstInt4) {
1177	        elementsPerRepeat = REPEAT_BYTE / sizeof(half); // 128
1178	        dstRepeatStride = BLOCK_MAX_PER_REPEAT / 4;     // 2 (64 bytes = 2 blocks for 128 packed int4 elements)
1179	        srcRepeatStride = BLOCK_MAX_PER_REPEAT;         // 8
1180	    } else if constexpr (isSrcInt4) {
1181	        elementsPerRepeat = REPEAT_BYTE / sizeof(half); // 128
1182	        dstRepeatStride = BLOCK_MAX_PER_REPEAT;         // 8
1183	        srcRepeatStride = BLOCK_MAX_PER_REPEAT / 4;     // 2 (64 bytes = 2 blocks for 128 packed int4 elements)
1184	    } else {
1185	        uint64_t repeatWidth =
1186	            static_cast<uint64_t>(max(sizeof(typename TileDataD::DType), sizeof(typename TileDataS::DType)));
1187	        dstRepeatStride =
1188	            repeatWidth == sizeof(typename TileDataD::DType) ?
1189	                BLOCK_MAX_PER_REPEAT :
1190	                (BLOCK_MAX_PER_REPEAT / sizeof(typename TileDataS::DType) * sizeof(typename TileDataD::DType));
1191	        srcRepeatStride =
1192	            repeatWidth == sizeof(typename TileDataS::DType) ?
1193	                BLOCK_MAX_PER_REPEAT :
1194	                (BLOCK_MAX_PER_REPEAT / sizeof(typename TileDataD::DType) * sizeof(typename TileDataS::DType));
1195	        elementsPerRepeat = REPEAT_BYTE / repeatWidth;
1196	    }
1197	}
