1199	// Helper: Check if this is a narrowing conversion that defaults to non-saturating mode
1200	template <typename TileDataD, typename TileDataS>
1201	constexpr bool kIsNarrowingCvt =
1202	    (std::is_same<typename TileDataD::DType, uint8_t>::value && std::is_same<typename TileDataS::DType, half>::value) ||
1203	    (std::is_same<typename TileDataD::DType, int8_t>::value && std::is_same<typename TileDataS::DType, half>::value) ||
1204	    (std::is_same<typename TileDataD::DType, int16_t>::value &&
1205	     std::is_same<typename TileDataS::DType, float>::value) ||
1206	    (std::is_same<typename TileDataD::DType, int16_t>::value && std::is_same<typename TileDataS::DType, half>::value) ||
1207	    (std::is_same<typename TileDataD::DType, int32_t>::value &&
1208	     std::is_same<typename TileDataS::DType, int64_t>::value) ||
1209	    (std::is_same<typename TileDataD::DType, int16_t>::value &&
1210	     std::is_same<typename TileDataS::DType, int32_t>::value);
