1212	// ============================================================================
1213	// High-Level Tile Conversion Interface
1214	// ============================================================================
1215	// TCVT_IMPL is the main entry point for tile data type conversion.
1216	// Calculates optimal repeat configuration and delegates to TCvt kernel.
1217	//
1218	// This is the main implementation with explicit satMode parameter.
1219	template <typename TileDataD, typename TileDataS>
1220	PTO_INTERNAL void TCVT_IMPL(
1221	    TileDataD& dst, TileDataS& src, RoundMode mode, SaturationMode satMode, bool needSetCtrl = true)
1222	{
1223	    unsigned dstRepeatStride, srcRepeatStride, elementsPerRepeat;
1224	    ComputeTCvtRepeatConfig<TileDataD, TileDataS>(elementsPerRepeat, dstRepeatStride, srcRepeatStride);
1225	
1226	    unsigned numRepeatPerLine = dst.GetValidCol() / elementsPerRepeat;
1227	    unsigned numRemainPerLine = dst.GetValidCol() % elementsPerRepeat;
1228	    constexpr unsigned SS = TileDataS::RowStride;
1229	    constexpr unsigned DS = TileDataD::RowStride;
1230	    unsigned validRow = dst.GetValidRow();
1231	    if (needSetCtrl) {
1232	        if constexpr (kIsNarrowingCvt<TileDataD, TileDataS>) {
1233	            TCvt<TileDataD, TileDataS, SS, DS, true>(
1234	                dst.data(), src.data(), mode, satMode, numRepeatPerLine, numRemainPerLine, validRow, elementsPerRepeat,
1235	                dstRepeatStride, srcRepeatStride);
1236	        } else {
1237	            TCvt<TileDataD, TileDataS, SS, DS, true>(
1238	                dst.data(), src.data(), mode, SaturationMode::ON, numRepeatPerLine, numRemainPerLine, validRow,
1239	                elementsPerRepeat, dstRepeatStride, srcRepeatStride);
1240	        }
1241	    } else {
1242	        if constexpr (kIsNarrowingCvt<TileDataD, TileDataS>) {
1243	            TCvt<TileDataD, TileDataS, SS, DS, false>(
1244	                dst.data(), src.data(), mode, satMode, numRepeatPerLine, numRemainPerLine, validRow, elementsPerRepeat,
1245	                dstRepeatStride, srcRepeatStride);
1246	        } else {
1247	            TCvt<TileDataD, TileDataS, SS, DS, false>(
1248	                dst.data(), src.data(), mode, SaturationMode::ON, numRepeatPerLine, numRemainPerLine, validRow,
1249	                elementsPerRepeat, dstRepeatStride, srcRepeatStride);
1250	        }
1251	    }
1252	}
