1294	// This overload provides conversion-specific default saturation modes:
1295	// - FP16→UINT8, FP16→INT8: defaults to OFF (PyTorch-compatible truncation)
1296	// - INT64→INT32, INT32→INT16: defaults to OFF (truncation behavior)
1297	// - All others: defaults to ON (native TCVT saturation)
1298	template <typename TileDataD, typename TileDataS>
1299	PTO_INTERNAL void TCVT_IMPL(TileDataD& dst, TileDataS& src, RoundMode mode, bool needSetCtrl = true)
1300	{
