47	inline uint16_t FloatToBf16BitsTrunc(float value) { return static_cast<uint16_t>(FloatToBits(value) >> bf16Bits); }
48	
49	inline uint16_t FloatToBf16BitsRound(float value)
50	{
51	    constexpr uint32_t bitsShift = 16;
52	    const uint32_t bits = FloatToBits(value);
53	    const uint32_t lsb = (bits >> bitsShift) & 1u;
54	    return static_cast<uint16_t>((bits + 0x7FFFu + lsb) >> bitsShift);
