98	inline float DecodeE4M3Fn(uint8_t code)
99	{
100	    const int sign = (code & 0x80u) ? -1 : 1;
101	    const int exp = (code >> 3) & 0x0Fu;
102	    const int mant = code & 0x07u;
103	    if (exp == 0) {
104	        if (mant == 0) {
105	            return sign < 0 ? -0.0f : 0.0f;
106	        }
107	        constexpr int scaleExp = 9;
108	        return static_cast<float>(sign) * std::ldexp(static_cast<float>(mant), -scaleExp);
109	    }
110	    if (exp == 0x0F && mant == 0x07) {
111	        return std::numeric_limits<float>::quiet_NaN();
112	    }
113	    const float significand = 1.0f + static_cast<float>(mant) / 8.0f;
114	    constexpr int scaleExp = 7;
115	    return static_cast<float>(sign) * std::ldexp(significand, exp - scaleExp);
116	}
117	
118	template <QuantScaleAlg scale_alg>
119	inline uint8_t EncodeE4M3Fn(float value)
120	{
121	    if (std::isnan(value)) {
122	        return 0x7Fu;
123	    }
124	    if (scale_alg == QuantScaleAlg::NV && std::fabs(value) < 0.0009765625f) {
125	        // FIX: Safe Sign-Retention Check mimicking Python's ml_dtypes underflow tracking
126	        if (std::signbit(value)) {
127	            return 0x80u; // Match negative zero output requirement
128	        } else {
129	            return 0x00u; // Clean positive zero
130	        }
131	    }
132	
133	    const float clipped = std::clamp(value, -448.0f, 448.0f);
134	    uint8_t bestCode = 0;
135	    float bestDistance = std::numeric_limits<float>::infinity();
136	    bool bestEven = true;
137	    constexpr int codeMax = 256;
138	    for (int code = 0; code < codeMax; ++code) {
139	        if ((code & 0x7F) == 0x7F) {
140	            continue;
141	        }
142	        const float candidate = DecodeE4M3Fn(static_cast<uint8_t>(code));
143	        const float distance = std::fabs(candidate - clipped);
144	        const bool isEven = (code & 1) == 0;
145	        if (distance < bestDistance || (distance == bestDistance && isEven && !bestEven) ||
146	            (distance == bestDistance && isEven == bestEven && static_cast<uint8_t>(code) < bestCode)) {
147	            bestDistance = distance;
148	            bestCode = static_cast<uint8_t>(code);
149	            bestEven = isEven;
150	        }
151	    }
152	    return bestCode;
153	}
