155	inline uint8_t EncodeE2M1Magic(float value)
156	{
157	    if (std::isnan(value)) {
158	        return 0x7u;
159	    }
160	    const uint32_t valueBits = FloatToBits(value);
161	    const uint8_t sign = static_cast<uint8_t>((valueBits >> 28) & 0x8u);
162	    const float absValue = std::fabs(value);
163	    if (std::isinf(absValue)) {
164	        return static_cast<uint8_t>(sign | 0x7u);
165	    }
166	
167	    const uint32_t absBits = FloatToBits(absValue);
168	    uint32_t biasedExp = (absBits & 0x7F800000u) >> 23;
169	    biasedExp = std::clamp<uint32_t>(biasedExp, 127u, 129u);
170	
171	    const uint32_t magicBits = (biasedExp + 22u) << 23;
172	    const uint32_t q = FloatToBits(absValue + BitsToFloat(magicBits)) - magicBits;
173	    const uint32_t baseCode = (biasedExp - 127u) << 1;
174	    const uint32_t magCode = std::min<uint32_t>(q + baseCode, 7u);
175	    return static_cast<uint8_t>(sign | magCode);
176	}
177	
178	inline uint8_t ComputeSharedExponent(float maxAbsValue)
179	{
180	    const uint32_t bits = FloatToBits(maxAbsValue);
181	    const uint32_t exponent = (bits & 0x7F800000u) >> 23;
182	    const uint32_t mantissa = bits & 0x007FFFFFu;
183	    if (exponent == 0xFFu && mantissa != 0u) {
184	        return 0xFFu;
185	    }
186	    if (exponent <= 8u) {
187	        return 0u;
188	    }
189	    return static_cast<uint8_t>(exponent - 8u);
190	}
191	
192	template <typename NvFormatSpec>
193	inline uint8_t ComputeNvSharedExponent(float maxAbsValue)
194	{
195	    if (maxAbsValue == 0.0f) {
196	        return 0;
197	    }
198	    constexpr float descaleMultiplier = NvFormatSpec::descaleMultiplier;
199	    const float descale = maxAbsValue * descaleMultiplier;
200	    const uint32_t bits = FloatToBits(descale);
201	    const uint32_t exponent = (bits & 0x7F800000u) >> 23;
202	    const uint32_t mantissa = bits & 0x007FFFFFu;
203	    if (exponent == 0xFFu) {
204	        return mantissa == 0u ? 0xFEu : 0xFFu;
205	    }
206	    const bool roundUp = mantissa > 0u && exponent != 0xFEu && !(exponent == 0u && mantissa <= 0x00400000u);
207	    return static_cast<uint8_t>(exponent + (roundUp ? 1u : 0u));
208	}
209	
210	inline uint8_t ComputeE2M1SharedExponent(float maxAbsValue)
211	{
212	    const uint32_t bits = FloatToBits(maxAbsValue);
213	    const uint32_t exponent = (bits & 0x7F800000u) >> 23;
214	    const uint32_t mantissa = bits & 0x007FFFFFu;
215	    if (exponent == 0xFFu && mantissa != 0u) {
216	        return 0xFFu;
217	    }
218	    if (exponent <= 2u) {
219	        return 0u;
220	    }
221	    return static_cast<uint8_t>(exponent - 2u);
222	}
223	
224	constexpr int SCALE_MIN_EXP = -127;
225	
226	inline float ComputeMxScalingFromExponent(uint8_t e8m0)
227	{
228	    if (e8m0 == 0xFFu) {
229	        return std::numeric_limits<float>::quiet_NaN();
230	    }
231	    const uint32_t scaleExp = 254u - static_cast<uint32_t>(e8m0);
232	    float scaling = BitsToFloat(scaleExp << 23);
233	    if (scaling == 0.0f) {
234	        scaling = std::ldexp(1.0f, SCALE_MIN_EXP);
235	    }
236	    return scaling;
237	}
238	
239	inline float ComputeNvScalingFromExponent(uint8_t e8m0)
240	{
241	    if (e8m0 == 0xFFu) {
242	        return std::numeric_limits<float>::quiet_NaN();
243	    }
244	    if (e8m0 == 0xFEu) {
245	        return std::ldexp(1.0f, SCALE_MIN_EXP);
246	    }
247	    return ComputeMxScalingFromExponent(e8m0);
248	}
249	
250	inline float ComputeE2M1ScalingFromExponent(uint8_t e8m0) { return ComputeMxScalingFromExponent(e8m0); }
251	
252	inline float ComputeScalingFromExponent(uint8_t e8m0) { return ComputeMxScalingFromExponent(e8m0); }
253	
254	inline std::vector<uint8_t> ReorderExponentZZ(const std::vector<uint8_t>& exp, int rows, int groupCols)
255	{
256	    constexpr int groupBlockSize = 2;
257	    constexpr int rowBlockSize = 16;
258	    PTO_CPU_ASSERT(
259	        rows % rowBlockSize == 0 && groupCols % groupBlockSize == 0,
260	        "Fix: MXFP8 NZ exponent reorder currently requires rows "
261	        "multiple of 16 and group cols multiple of 2.");
262	    const int rowBlocks = rows / rowBlockSize;
263	    const int groupBlocks = groupCols / groupBlockSize;
264	    std::vector<uint8_t> reordered;
265	    reordered.reserve(exp.size());
266	    for (int rb = 0; rb < rowBlocks; ++rb) {
267	        for (int gb = 0; gb < groupBlocks; ++gb) {
268	            for (int innerRow = 0; innerRow < rowBlockSize; ++innerRow) {
269	                for (int innerGroup = 0; innerGroup < groupBlockSize; ++innerGroup) {
270	                    const int row = rb * rowBlockSize + innerRow;
271	                    const int group = gb * groupBlockSize + innerGroup;
272	                    reordered.push_back(exp[row * groupCols + group]);
273	                }
274	            }
275	        }
276	    }
277	    return reordered;
278	}
279	
280	template <int grp_axis, QuantType quant_type, QuantScaleAlg scale_alg, typename TileDataSrc>
281	inline float ComputeMxGroupMax(TileDataSrc& src, int axis, int group)
282	{
283	    float maxAbsValue = 0.0f;
284	    uint16_t maxAbsBf16Bits = 0;
285	    constexpr int groupSize = 32;
286	    for (int inner = 0; inner < groupSize; ++inner) {
287	        int row = grp_axis == 1 ? axis : (group * groupSize + inner);
288	        int col = grp_axis == 1 ? (group * groupSize + inner) : axis;
289	        const float value = src.data()[GetTileElementOffset<TileDataSrc>(row, col)];
290	        if constexpr (
291	            quant_type == QuantType::MXFP8 || (quant_type == QuantType::MXFP4_E2M1 && scale_alg == QuantScaleAlg::NV)) {
292	            if constexpr (quant_type == QuantType::MXFP4_E2M1) {
293	                if (std::isnan(value)) {
294	                    return value;
295	                }
296	            }
297	            maxAbsValue = std::max(maxAbsValue, std::fabs(value));
298	        } else {
299	            maxAbsBf16Bits = std::max(maxAbsBf16Bits, AbsBf16BitsFromFloat(value));
300	        }
301	    }
302	    if constexpr (quant_type == QuantType::MXFP4_E2M1 && scale_alg == QuantScaleAlg::OCP) {
303	        maxAbsValue = Bf16BitsToFloat(maxAbsBf16Bits);
304	    }
305	    return maxAbsValue;
306	}
307	
308	template <QuantType quant_type>
309	inline uint8_t ComputeMxSharedExponent(float maxAbsValue)
310	{
311	    if constexpr (quant_type == QuantType::MXFP8) {
312	        return ComputeSharedExponent(maxAbsValue);
313	    }
314	    return ComputeE2M1SharedExponent(maxAbsValue);
315	}
316	
317	template <QuantType quant_type>
318	inline float ComputeMxGroupScaling(uint8_t e8m0)
319	{
320	    if constexpr (quant_type == QuantType::MXFP8) {
321	        return ComputeScalingFromExponent(e8m0);
322	    }
323	    return ComputeE2M1ScalingFromExponent(e8m0);
324	}
325	
326	template <QuantType quant_type, QuantScaleAlg scale_alg>
327	inline uint8_t ComputeMxSharedExponent(float maxAbsValue)
328	{
329	    if constexpr (quant_type == QuantType::MXFP8 && scale_alg == QuantScaleAlg::NV) {
330	        return ComputeNvSharedExponent<NvMxFp8E4M3Spec>(maxAbsValue);
331	    } else if constexpr (quant_type == QuantType::MXFP4_E2M1 && scale_alg == QuantScaleAlg::NV) {
332	        return ComputeNvSharedExponent<NvMxFp4E2M1Spec>(maxAbsValue);
333	    }
334	    return ComputeMxSharedExponent<quant_type>(maxAbsValue);
335	}
336	
337	template <QuantType quant_type, QuantScaleAlg scale_alg>
338	inline float ComputeMxGroupScaling(float maxAbsValue, uint8_t e8m0)
339	{
340	    if (e8m0 == 0xFFu) {
341	        return maxAbsValue;
342	    }
343	    if constexpr (scale_alg == QuantScaleAlg::NV) {
344	        return ComputeNvScalingFromExponent(e8m0);
345	    }
346	    return ComputeMxGroupScaling<quant_type>(e8m0);
347	}
348	
349	template <
350	    QuantType quant_type, QuantScaleAlg scale_alg, typename TileDataOut, typename TileDataSrc, typename FlatScalingTile>
351	inline void StoreMxEncodedValue(
352	    TileDataOut& dst, TileDataSrc& src, FlatScalingTile& flatScaling, int row, int col, int flatGroupIdx,
353	    float groupScaling)
354	{
355	    using SrcT = typename TileDataSrc::DType;
356	    using DstT = typename TileDataOut::DType;
357	    flatScaling.data()[flatGroupIdx] = static_cast<typename FlatScalingTile::DType>(groupScaling);
358	    if constexpr (quant_type == QuantType::MXFP8) {
359	        const float value = static_cast<float>(src.data()[GetTileElementOffset<TileDataSrc>(row, col)]);
360	        const uint8_t encoded = EncodeE4M3Fn<scale_alg>(value * groupScaling);
361	        dst.SetElement(row, col, static_cast<DstT>(encoded));
362	    } else {
363	        uint8_t finalEncoded = NvMxFp4E2M1Spec::PS_MAX;
364	        if (std::isinf(groupScaling)) {
365	            finalEncoded = (groupScaling > 0) ? NvMxFp4E2M1Spec::PS_MAX : NvMxFp4E2M1Spec::NG_MIN;
366	        } else if (!std::isnan(groupScaling)) {
367	            const float value = static_cast<float>(src.data()[GetTileElementOffset<TileDataSrc>(row, col)]);
368	            finalEncoded = EncodeE2M1Magic(ApplyE2M1ScaleForSource<SrcT>(static_cast<SrcT>(value), groupScaling));
369	        }
370	        dst.SetElement(row, col, DstT::FromRaw(finalEncoded));
371	    }
372	}
373	
374	template <
375	    int grp_axis, QuantType quant_type, QuantScaleAlg scale_alg, typename TileDataOut, typename TileDataSrc,
376	    typename FlatScalingTile>
377	inline void QuantizeMxGroup(
378	    TileDataOut& dst, TileDataSrc& src, FlatScalingTile& flatScaling, int axis, int group, int flatGroupIdx,
379	    float groupScaling)
380	{
381	    constexpr int groupSize = 32;
382	    for (int inner = 0; inner < groupSize; ++inner) {
383	        int row = grp_axis == 1 ? axis : (group * groupSize + inner);
384	        int col = grp_axis == 1 ? (group * groupSize + inner) : axis;
385	        StoreMxEncodedValue<quant_type, scale_alg>(dst, src, flatScaling, row, col, flatGroupIdx, groupScaling);
386	    }
387	}
388	
389	template <typename TileData>
390	using FlatMxTile =
391	    Tile<TileType::Vec, typename TileData::DType, 1, TileData::Rows * TileData::Cols, BLayout::RowMajor, -1, -1>;
392	
393	template <
394	    int grp_axis, QuantType quant_type, QuantScaleAlg scale_alg, typename TileDataOut, typename TileDataSrc,
395	    typename TileDataExp>
396	inline void CheckMxQuantTypes()
397	{
398	    static_assert(
399	        quant_type == QuantType::MXFP8 || quant_type == QuantType::MXFP4_E2M1,
400	        "Fix: MX overload is reserved for MXFP8/MXFP4_E2M1.");
401	    static_assert(
402	        scale_alg == QuantScaleAlg::OCP || scale_alg == QuantScaleAlg::NV,
403	        "Fix: MX scale algorithm must be OCP or NV.");
404	
405	    static_assert(
406	        TileDataSrc::isRowMajor && TileDataOut::isRowMajor && TileDataSrc::Rows == TileDataOut::Rows &&
407	            TileDataSrc::Cols == TileDataOut::Cols,
408	        "Src and Out tiles should have the same BFractal layout and static shape!");
409	    static_assert(
410	        (grp_axis == 1 && (TileDataSrc::Cols % 32 == 0)) || (grp_axis == 0 && (TileDataSrc::Rows % 32 == 0)),
411	        "Src Rows/Cols should be multiple of 32 for ND/DN quant mode!");
412	
413	    using SrcT = typename TileDataSrc::DType;
414	    if constexpr (quant_type == QuantType::MXFP8) {
415	        static_assert(
416	            std::is_same_v<SrcT, float> || std::is_same_v<SrcT, half> || std::is_same_v<SrcT, aclFloat16> ||
417	                std::is_same_v<SrcT, bfloat16_t>,
418	            "Fix: MXFP8 CPU sim supports float/float16/bfloat16 source.");
419	        static_assert(std::is_same_v<typename TileDataOut::DType, int8_t>, "Fix: MXFP8 output must be int8 bytes.");
420	    } else {
421	        static_assert(
422	            std::is_same_v<SrcT, float> || std::is_same_v<SrcT, half> || std::is_same_v<SrcT, aclFloat16> ||
423	                std::is_same_v<SrcT, bfloat16_t>,
424	            "Fix: MXFP4_E2M1 CPU sim supports float/float16/bfloat16 source.");
425	        static_assert(
426	            std::is_same_v<typename TileDataOut::DType, float4_e2m1x2_t>,
427	            "Fix: MXFP4_E2M1 output must be float4_e2m1x2_t.");
428	    }
429	    static_assert(std::is_same_v<typename TileDataExp::DType, uint8_t>, "Fix: MXFP8 exponent must be uint8 bytes.");
430	}
431	
432	template <typename TileDataExp, typename TileDataMax, typename TileDataScaling>
433	inline void CheckMxQuantInputs(TileDataExp* exp, TileDataMax* max, TileDataScaling* scaling)
434	{
435	    PTO_CPU_ASSERT(exp != nullptr && max != nullptr && scaling != nullptr, "Fix: MX quant requires tiles.");
436	}
