438	template <typename FlatTileData, typename TileData>
439	inline void FlattenMxTile(FlatTileData& flatTile, TileData& tile)
440	{
441	    TRESHAPE_IMPL(flatTile, tile);
442	}
443	
444	template <typename TileData, typename FlatTileData>
445	inline void RestoreMxTile(TileData& tile, FlatTileData& flatTile)
446	{
447	    TRESHAPE_IMPL(tile, flatTile);
448	}
