450	template <QuantType quant_type, typename TileDataOut>
451	inline void InitMxOutput(TileDataOut& dst)
452	{
453	    if constexpr (quant_type == QuantType::MXFP4_E2M1) {
454	        std::fill(
455	            reinterpret_cast<uint8_t*>(dst.data()),
456	            reinterpret_cast<uint8_t*>(dst.data()) + TileDataOut::Rows * TileDataOut::Cols, 0);
457	    }
458	}
459	
460	template <
461	    int grp_axis, QuantType quant_type, QuantScaleAlg scale_alg, typename TileDataOut, typename TileDataSrc,
462	    typename TileDataExp, typename FlatMaxTile, typename FlatScalingTile>
463	inline void QuantizeMxTile(
464	    TileDataOut& dst, TileDataSrc& src, TileDataExp& exp, FlatMaxTile& flatMax, FlatScalingTile& flatScaling)
465	{
466	    const int rows = (grp_axis == 1) ? src.GetValidRow() : TileDataSrc::Rows;
467	    const int cols = (grp_axis == 1) ? TileDataSrc::Cols : src.GetValidCol();
468	
469	    const int numGroupsAlongAxis = (grp_axis == 1) ? (cols / 32) : (rows / 32);
470	    const int numElementsAlongAxis = (grp_axis == 1) ? rows : cols;
471	
472	    for (int i = 0; i < numElementsAlongAxis; ++i) {
473	        for (int group = 0; group < numGroupsAlongAxis; ++group) {
474	            const int row = (grp_axis == 1) ? i : group; // This needs careful mapping logic
475	            const int col = (grp_axis == 1) ? group : i;
476	
477	            const int flatGroupIdx =
478	                (grp_axis == 1) ? (i * numGroupsAlongAxis + group) : (group * numElementsAlongAxis + i);
479	
480	            const float maxAbsValue = ComputeMxGroupMax<grp_axis, quant_type, scale_alg>(src, i, group);
481	            const uint8_t e8m0 = ComputeMxSharedExponent<quant_type, scale_alg>(maxAbsValue);
482	            const float groupScaling = ComputeMxGroupScaling<quant_type, scale_alg>(maxAbsValue, e8m0);
483	
484	            flatMax.data()[flatGroupIdx] = static_cast<typename FlatMaxTile::DType>(maxAbsValue);
485	            exp.data()[GetTileElementOffset<TileDataExp>(row, col)] = e8m0;
486	
487	            QuantizeMxGroup<grp_axis, quant_type, scale_alg>(
488	                dst, src, flatScaling, i, group, flatGroupIdx, groupScaling);
489	        }
490	    }
491	}
492	} // namespace cpu_quant
493	
494	template <QuantType quant_type, typename TileDataOut, typename TileDataSrc, typename TileDataPara>
495	PTO_INTERNAL void TQUANT_IMPL(TileDataOut& dst, TileDataSrc& src, TileDataPara& scale, TileDataPara* offset = nullptr)
496	{
497	    using SrcT = typename TileDataSrc::DType;
498	    static_assert(std::is_same_v<SrcT, float>, "Fix: Input has to be float 32");
499	
500	    for (int row = 0; row < src.GetValidRow(); ++row) {
501	        for (int col = 0; col < src.GetValidCol(); ++col) {
502	            const float srcValue = src.data()[GetTileElementOffset<TileDataSrc>(row, col)];
503	            const float invScale = static_cast<float>(cpu_quant::GetParamValue(scale, row, 0));
504	            if constexpr (quant_type == QuantType::INT8_SYM) {
505	                static_assert(
506	                    std::is_same_v<typename TileDataOut::DType, int8_t>,
507	                    "Fix: Quant INT8 sym: Out data type has to be int8");
508	                dst.data()[GetTileElementOffset<TileDataOut>(row, col)] = cpu_quant::ClampInt8(srcValue * invScale);
509	            } else {
510	                static_assert(
511	                    std::is_same_v<typename TileDataOut::DType, uint8_t>,
512	                    "Fix: Quant INT8 asym: Out data type has to be uint8");
513	                PTO_CPU_ASSERT(offset != nullptr, "Fix: Quant INT8 asym requires offset.");
514	                const float zeroPoint = static_cast<float>(cpu_quant::GetParamValue(*offset, row, 0));
515	                dst.data()[GetTileElementOffset<TileDataOut>(row, col)] =
516	                    cpu_quant::ClampUint8(srcValue * invScale + zeroPoint);
517	            }
518	        }
519	    }
520	}
521	
522	template <
523	    int grp_axis, QuantType quant_type, QuantScaleAlg scale_alg, typename TileDataOut, typename TileDataSrc,
524	    typename TileDataExp, typename TileDataMax, typename TileDataScaling>
525	inline void TQuantMxCpuImpl(
526	    TileDataOut& dst, TileDataSrc& src, TileDataExp* exp, TileDataMax* max, TileDataScaling* scaling)
527	{
528	    cpu_quant::CheckMxQuantTypes<grp_axis, quant_type, scale_alg, TileDataOut, TileDataSrc, TileDataExp>();
529	    cpu_quant::CheckMxQuantInputs(exp, max, scaling);
530	
531	    using FlatMaxTile = cpu_quant::FlatMxTile<TileDataMax>;
532	    using FlatScalingTile = cpu_quant::FlatMxTile<TileDataScaling>;
533	
534	    FlatMaxTile flatMax(1, TileDataMax::Rows * TileDataMax::Cols);
535	    cpu_quant::FlattenMxTile(flatMax, *max);
536	
537	    FlatScalingTile flatScaling(1, TileDataScaling::Rows * TileDataScaling::Cols);
538	    cpu_quant::FlattenMxTile(flatScaling, *scaling);
539	
540	    cpu_quant::InitMxOutput<quant_type>(dst);
541	    cpu_quant::QuantizeMxTile<grp_axis, quant_type, scale_alg>(dst, src, *exp, flatMax, flatScaling);
542	
543	    cpu_quant::RestoreMxTile(*max, flatMax);
544	    cpu_quant::RestoreMxTile(*scaling, flatScaling);
545	}
546	
547	template <
548	    QuantType quant_type, typename TileDataOut, typename TileDataSrc, typename TileDataExp, typename TileDataMax,
549	    typename TileDataScaling>
550	PTO_INTERNAL void TQUANT_IMPL(
551	    TileDataOut& dst, TileDataSrc& src, TileDataExp* exp, TileDataMax* max, TileDataScaling* scaling)
552	{
553	    TQuantMxCpuImpl<1, quant_type, QuantScaleAlg::OCP>(dst, src, exp, max, scaling);
554	}
555	
556	template <
557	    int grp_axis, MxQuantAlg mx_alg, typename TileDataOut, typename TileDataSrc, typename TileDataExp,
558	    typename TileDataMax, typename TileDataScaling>
559	PTO_INTERNAL void TQUANT_IMPL(
560	    TileDataOut& dst, TileDataSrc& src, TileDataExp* exp, TileDataMax* max, TileDataScaling* scaling)
561	{
562	    constexpr QuantScaleAlg scale_alg = (mx_alg == MxQuantAlg::OcpMxFp4E2M1 || mx_alg == MxQuantAlg::OcpMxFp8E4M3) ?
563	                                            QuantScaleAlg::OCP :
564	                                            QuantScaleAlg::NV;
565	    constexpr QuantType quant_type = (mx_alg == MxQuantAlg::OcpMxFp4E2M1 || mx_alg == MxQuantAlg::NvMxFp4E2M1) ?
566	                                         QuantType::MXFP4_E2M1 :
567	                                         QuantType::MXFP8;
568	    TQuantMxCpuImpl<grp_axis, quant_type, scale_alg>(dst, src, exp, max, scaling);
569	}
570	
571	template <
572	    QuantType quant_type, QuantScaleAlg scale_alg, typename TileDataOut, typename TileDataSrc, typename TileDataExp,
573	    typename TileDataMax, typename TileDataScaling>
574	PTO_INTERNAL void TQUANT_IMPL(
575	    TileDataOut& dst, TileDataSrc& src, TileDataExp* exp, TileDataMax* max, TileDataScaling* scaling)
576	{
577	    static_assert(
578	        quant_type == QuantType::MXFP8 || quant_type == QuantType::MXFP4_E2M1,
579	        "Fix: scale algorithm overload is reserved for MXFP8/MXFP4_E2M1.");
580	    TQuantMxCpuImpl<1, quant_type, scale_alg>(dst, src, exp, max, scaling);
581	}
582	
583	template <
584	    QuantType quant_type, VecStoreMode store_mode, typename TileDataOut, typename TileDataSrc, typename TileDataExp,
585	    typename TileDataMax, typename TileDataScaling>
586	PTO_INTERNAL void TQUANT_IMPL(
587	    TileDataOut& dst, TileDataSrc& src, TileDataExp* exp, TileDataMax* max, TileDataScaling* scaling,
588	    TileDataExp* exp_zz)
589	{
590	    static_assert(quant_type == QuantType::MXFP8, "Fix: MX overload is reserved for MXFP8.");
591	    static_assert(store_mode == VecStoreMode::NZ, "Fix: This overload is reserved for MXFP8 NZ mode.");
592	
593	    TQUANT_IMPL<quant_type, TileDataOut, TileDataSrc, TileDataExp, TileDataMax, TileDataScaling>(
594	        dst, src, exp, max, scaling);
595	
596	    PTO_CPU_ASSERT(exp_zz != nullptr, "Fix: MXFP8 NZ mode requires reordered exponents.");
597	    const int rows = src.GetValidRow();
598	    const int groupCols = src.GetValidCol() / 32;
599	    const int totalGroups = rows * groupCols;
600	    std::vector<uint8_t> expValues(totalGroups);
601	    for (int i = 0; i < totalGroups; ++i) {
602	        expValues[i] = exp->data()[GetTileElementOffset<TileDataExp>(0, i)];
603	    }
604	    const auto reordered = cpu_quant::ReorderExponentZZ(expValues, rows, groupCols);
605	    for (int i = 0; i < totalGroups; ++i) {
606	        exp_zz->data()[GetTileElementOffset<TileDataExp>(0, i)] = reordered[i];
607	    }
608	}
609	} // namespace pto
610	
611	#endif
