25	uint8_t DecodeCandidateCode(uint8_t code, float& value)
26	{
27	    const int sign = (code & 0x80u) ? -1 : 1;
28	    const int exp = (code >> 3) & 0x0Fu;
29	    const int mant = code & 0x07u;
30	    if (exp == 0) {
31	        value = (mant == 0) ? (sign < 0 ? -0.0f : 0.0f) :
32	                              static_cast<float>(sign) * std::ldexp(static_cast<float>(mant), -9);
33	        return code;
34	    }
35	    value = static_cast<float>(sign) * std::ldexp(1.0f + static_cast<float>(mant) / 8.0f, exp - 7);
36	    return code;
37	}
38	
39	uint8_t EncodeE4M3Fn(float value)
40	{
41	    if (std::isnan(value)) {
42	        return 0x7Fu;
43	    }
44	    const float clipped = std::clamp(value, -448.0f, 448.0f);
45	    uint8_t best = 0;
46	    float bestDistance = std::numeric_limits<float>::infinity();
47	    bool bestEven = true;
48	    for (int code = 0; code < 256; ++code) {
49	        if ((code & 0x7F) == 0x7F) {
50	            continue;
51	        }
52	        float candidate = 0.0f;
53	        DecodeCandidateCode(static_cast<uint8_t>(code), candidate);
54	        const float distance = std::fabs(candidate - clipped);
55	        const bool isEven = (code & 1) == 0;
56	        if (distance < bestDistance || (distance == bestDistance && isEven && !bestEven) ||
57	            (distance == bestDistance && isEven == bestEven && static_cast<uint8_t>(code) < best)) {
58	            bestDistance = distance;
59	            best = static_cast<uint8_t>(code);
60	            bestEven = isEven;
61	        }
62	    }
63	    return best;
64	}
