66	std::vector<uint8_t> ReorderExponentZZ(const std::vector<uint8_t>& exp, int rows, int groupCols)
67	{
68	    std::vector<uint8_t> reordered;
69	    reordered.reserve(exp.size());
70	    for (int rb = 0; rb < rows / 16; ++rb) {
71	        for (int gb = 0; gb < groupCols / 2; ++gb) {
72	            for (int innerRow = 0; innerRow < 16; ++innerRow) {
73	                for (int innerGroup = 0; innerGroup < 2; ++innerGroup) {
74	                    reordered.push_back(exp[(rb * 16 + innerRow) * groupCols + gb * 2 + innerGroup]);
75	                }
76	            }
77	        }
78	    }
79	    return reordered;
80	}
