92	        -std::nextafter(448.0f, 0.0f),
93	        448.0f,
94	        -448.0f,
95	        std::nextafter(448.0f, std::numeric_limits<float>::infinity()),
96	        -std::nextafter(448.0f, -std::numeric_limits<float>::infinity()),
97	        896.0f,
98	        std::nextafter(896.0f, std::numeric_limits<float>::infinity()),
99	        std::numeric_limits<float>::infinity(),
100	        std::numeric_limits<float>::quiet_NaN(),
101	    };
102	}
