104	template <typename SrcTile>
105	void FillMxFp8BoundarySource(SrcTile& src)
106	{
107	    const std::vector<float> pattern = MxFp8BoundaryPattern();
108	    for (int row = 0; row < src.GetValidRow(); ++row) {
109	        for (int group = 0; group < src.GetValidCol() / 32; ++group) {
110	            for (int inner = 0; inner < 32; ++inner) {
111	                float value = pattern[inner % pattern.size()];
112	                if (row == 0 && group == 0) {
113	                    value = 0.0f;
114	                } else if (group == 1) {
115	                    value = (inner & 1) == 0 ? 448.0f : static_cast<float>(static_cast<aclFloat16>(448.25f));
116	                } else if (group == 2) {
117	                    value = (inner & 1) == 0 ? 896.0f : static_cast<float>(static_cast<aclFloat16>(896.5f));
118	                }
119	                src.data()[GetTileElementOffset<SrcTile>(row, group * 32 + inner)] =
120	                    static_cast<typename SrcTile::DType>(value);
121	            }
122	        }
123	    }
124	}
