126	template <
127	    QuantScaleAlg scaleAlg, typename SrcTile, typename DstTile, typename ExpTile, typename MaxTile,
128	    typename ScalingTile>
129	void ExpectMxFp8Result(SrcTile& src, DstTile& dst, ExpTile& exp, MaxTile& max, ScalingTile& scaling)
130	{
131	    for (int row = 0; row < src.GetValidRow(); ++row) {
132	        for (int group = 0; group < src.GetValidCol() / 32; ++group) {
133	            float maxAbs = 0.0f;
134	            for (int inner = 0; inner < 32; ++inner) {
135	                const float value =
136	                    static_cast<float>(src.data()[GetTileElementOffset<SrcTile>(row, group * 32 + inner)]);
137	                maxAbs = std::max(maxAbs, std::fabs(value));
138	            }
139	            const uint8_t expectedExp = cpu_quant::ComputeMxSharedExponent<QuantType::MXFP8, scaleAlg>(maxAbs);
140	            const float expectedScaling =
141	                cpu_quant::ComputeMxGroupScaling<QuantType::MXFP8, scaleAlg>(maxAbs, expectedExp);
142	            const int flatGroupIdx = row * (src.GetValidCol() / 32) + group;
143	            EXPECT_EQ(exp.data()[GetTileElementOffset<ExpTile>(row, group)], expectedExp);
144	            EXPECT_FLOAT_EQ(max.data()[flatGroupIdx], maxAbs);
145	            if (std::isnan(expectedScaling)) {
146	                EXPECT_TRUE(std::isnan(scaling.data()[flatGroupIdx]));
147	            } else {
148	                EXPECT_FLOAT_EQ(scaling.data()[flatGroupIdx], expectedScaling);
149	            }
150	            for (int inner = 0; inner < 32; ++inner) {
151	                const int col = group * 32 + inner;
152	                const float value = static_cast<float>(src.data()[GetTileElementOffset<SrcTile>(row, col)]);
153	                const uint8_t expectedByte = pto::cpu_quant::EncodeE4M3Fn<scaleAlg>(value * expectedScaling);
154	                EXPECT_EQ(static_cast<uint8_t>(dst.data()[GetTileElementOffset<DstTile>(row, col)]), expectedByte);
155	            }
156	        }
157	    }
158	}
