443	enum class MxFp4Case {
444	    Special,
445	    Subnormal,
446	    Rounding,
447	    ExpRandomA,
448	    ExpRandomB,
449	    Mixed,
450	};
451	
452	float MakeMxFp4ExpRandomValue(int index, int seed)
453	{
454	    const int exponent = -24 + ((index * 13 + seed * 17) % 40);
455	    const float mantissa = 1.0f + static_cast<float>((index * 29 + seed * 11) % 1024) / 1024.0f;
456	    const float sign = ((index + seed) % 5 < 2) ? -1.0f : 1.0f;
457	    return sign * std::ldexp(mantissa, exponent);
458	}
459	
460	const float* GetMxFp4SpecialValues(size_t& count)
461	{
462	    static const float specialValues[] = {
463	        0.0f,
464	        -0.0f,
465	        std::numeric_limits<float>::infinity(),
466	        -std::numeric_limits<float>::infinity(),
467	        std::numeric_limits<float>::quiet_NaN(),
468	        65504.0f,
469	        -65504.0f,
470	        6.0f,
471	        -6.0f,
472	        4.0f,
473	        -4.0f,
474	        1.5f,
475	        -1.5f,
476	        0.5f,
477	        -0.5f,
478	        0.25f,
479	    };
480	    count = sizeof(specialValues) / sizeof(specialValues[0]);
481	    return specialValues;
482	}
483	
484	const float* GetMxFp4RoundingValues(size_t& count)
485	{
486	    static const float roundingValues[] = {
487	        4.0f,   -4.0f,  3.75f, -3.75f, 3.5f,   -3.5f,   3.0f,  -3.0f,  2.5f,   -2.5f,   2.25f,
488	        -2.25f, 2.0f,   -2.0f, 1.75f,  -1.75f, 1.5f,    -1.5f, 1.25f,  -1.25f, 1.0f,    -1.0f,
489	        0.75f,  -0.75f, 0.5f,  -0.5f,  0.375f, -0.375f, 0.25f, -0.25f, 0.125f, -0.125f,
490	    };
491	    count = sizeof(roundingValues) / sizeof(roundingValues[0]);
492	    return roundingValues;
493	}
494	
495	float MakeMxFp4SpecialValue(int index)
496	{
497	    size_t count = 0;
498	    const float* values = GetMxFp4SpecialValues(count);
499	    return values[index % count];
500	}
501	
502	float MakeMxFp4RoundingValue(int index)
503	{
504	    size_t count = 0;
505	    const float* values = GetMxFp4RoundingValues(count);
506	    return values[index % count];
507	}
508	
509	float MakeMxFp4SubnormalValue(int index)
510	{
511	    const float value = std::ldexp(static_cast<float>((index % 1023) + 1), -24);
512	    return (index & 1) ? -value : value;
513	}
514	
515	float MakeMxFp4MixedValue(int index)
516	{
517	    switch ((index / 32) % 4) {
518	        case 0:
519	            return MakeMxFp4SpecialValue(index);
520	        case 1:
521	            return MakeMxFp4SubnormalValue(index);
522	        case 2:
523	            return MakeMxFp4RoundingValue(index);
524	        default:
525	            return MakeMxFp4ExpRandomValue(index, 71);
526	    }
527	}
528	
529	float MakeMxFp4CaseValue(MxFp4Case caseId, int index)
530	{
531	    switch (caseId) {
532	        case MxFp4Case::Special:
533	            return MakeMxFp4SpecialValue(index);
534	        case MxFp4Case::Subnormal:
535	            return MakeMxFp4SubnormalValue(index);
536	        case MxFp4Case::Rounding:
537	            return MakeMxFp4RoundingValue(index);
538	        case MxFp4Case::ExpRandomA:
539	            return MakeMxFp4ExpRandomValue(index, 3);
540	        case MxFp4Case::ExpRandomB:
541	            return MakeMxFp4ExpRandomValue(index, 41);
542	        case MxFp4Case::Mixed:
543	            return MakeMxFp4MixedValue(index);
544	    }
545	    return 0.0f;
546	}
